def _text_hash(content: str) -> str:
    return "sha256:" + hashlib.sha256(content.encode("utf-8")).hexdigest()


def _file_hash(path: Path) -> str:
    if path.is_symlink():
        raise LocalWorkflowError(f"HK export contains symlinked file: {path}")
