def _compare_export_metadata(
    current: dict[str, object], recorded: dict[str, object]
) -> list[str]:
    ignored = {
        "generated_at",
        "dirty",
        "sync_status",
        "ready_status",
        "ready",
        "git_sha",
        "target_root",
        "target_scope",
        "file_hashes",
    }
    mismatches: list[str] = []
    for key, value in current.items():
        if key in ignored:
            continue
        if recorded.get(key) != value:
            mismatches.append(key)
    return mismatches


